// Helpers
const strip = s => (s || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const fmt = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;

// Input (KEEP name)
const tasks = ($json.data || []).map(t => ({
  name: t.name,                // <-- needed for link
  date: t.date,
  priority: t.priority,
  desc: strip(t.description).slice(0, 200)
}));

if (!tasks.length) return [{ json: { weekTotal: 0, days: [] } }];

// Find Monday of that week
const minDateStr = tasks.map(t => t.date).sort()[0];
const base = new Date(`${minDateStr}T00:00:00`);
const dow = base.getDay();                 // 0 Sun..6 Sat
base.setDate(base.getDate() - ((dow + 6) % 7));

// Build Mon→Fri skeleton
/** @type {{label:string,date:string,total:number,items:Array<any>}[]} */
const days = ['Monday','Tuesday','Wednesday','Thursday','Friday'].map((label, i) => {
  const d = new Date(base); d.setDate(base.getDate() + i);
  return { label, date: fmt(d), total: 0, items: /** @type {any[]} */([]) };
});

// Group + pre-number
for (const t of tasks) {
  const bucket = days.find(x => x.date === t.date);
  if (!bucket) continue;
  const n = bucket.items.length + 1;
  bucket.items.push({
    n,                    // numbering to print
    name: t.name,         // <-- keep name
    priority: t.priority,
    desc: t.desc
  });
  bucket.total++;
}

return [{ json: { weekTotal: tasks.length, days } }];

const strip = s => (s ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

const d = $json.data || {};
const clean = strip(d.description).slice(0, 200);

return [{
  json: {
    ...$json,
    data: { ...d, description_clean: clean }
  }
}];

// INIT RUN METRICS
// Expects: $json.nextMon, $json.nextFri (YYYY-MM-DD)
// Adds: $json._metrics with run_id, timestamps, week window, and counters.

function uuid() {
  try { return global.crypto.randomUUID(); }
  catch { return `${Date.now()}-${Math.random().toString(16).slice(2)}`; }
}

// Format a timezone-local ISO-like string (no timezone suffix)
function localISO(date, timeZone) {
  const parts = new Intl.DateTimeFormat('sv-SE', {
    timeZone,
    hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit'
  }).formatToParts(date).reduce((acc, p) => (acc[p.type] = p.value, acc), {});
  return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}`;
}

const tz = 'Europe/Riga';
const now = new Date();

const prev = $json._metrics || {};
const metrics = {
  // identifiers
  run_id: prev.run_id || uuid(),

  // timing
  tz,
  start_ts: prev.start_ts || now.toISOString(),          // UTC
  start_ts_riga: prev.start_ts_riga || localISO(now, tz),// Riga local clock (readable)

  // reporting window
  week_start: $json.nextMon,   // from previous node
  week_end:   $json.nextFri,

  // counters (initialized; may be incremented later)
  failures: prev.failures ?? 0,
  prompt_tokens: prev.prompt_tokens ?? 0,
  completion_tokens: prev.completion_tokens ?? 0,
  token_cost_eur: prev.token_cost_eur ?? 0
};

// pass through original payload + _metrics
return [{ 
  ...$json,
  _metrics: metrics
}];

// CAPTURE TASK COUNTS
// Goal: emit one summary item with how many ERP tasks we have.
// Works with either shape:
//  A) Single aggregated item: { data: [ {name, ...}, ... ] }
//  B) Many items (each is a ToDo): [{name,...}, {name,...}, ...]
// Does NOT reference $node[…] or _metrics (to avoid context errors).

function arrLen(x) { return Array.isArray(x) ? x.length : 0; }

const items = $items();   // all inbound items for this node
let count = 0;

if (items.length === 1) {
  // Typical after Aggregate: one item with .json.data = array
  const j = items[0]?.json ?? {};
  if (Array.isArray(j.data)) {
    count = j.data.length;
  } else {
    // Fallback: if config changed and it's an array of items nested differently
    count = arrLen(j.items);
  }
} else {
  // If previous node produced many items (each representing a task)
  count = items.length;
}

// Emit a single summary item. We'll merge this at the join hub.
return [{
  tasks_from_erpnext: count,
  // Optional: keep a small diagnostic sample to help debug shape changes
  _sample_first_item: (items[0]?.json && JSON.stringify(items[0].json).slice(0, 300)) || null
}];

// TITLE USAGE TAP — robust token accounting for per-item title/summary LLM
// Placement: immediately after "AI Title Generator".
// Settings: Run Once for All Items = ON

function isNum(x){ return typeof x === 'number' && isFinite(x); }

// Traverse any shape and collect usage
function sumUsageDeep(root){
  let prompt = 0, completion = 0, total = 0, found = false;
  const stack = [root];

  while (stack.length){
    const cur = stack.pop();
    if (!cur || typeof cur !== 'object') continue;

    // Drill into common containers
    if (cur.usage) stack.push(cur.usage);
    if (cur.token_usage) stack.push(cur.token_usage);
    if (cur.metrics) stack.push(cur.metrics);
    if (Array.isArray(cur.choices)) for (const ch of cur.choices) stack.push(ch);
    if (cur.response) stack.push(cur.response);

    for (const [k, v] of Object.entries(cur)){
      if (v && typeof v === 'object') stack.push(v);
      if (!isNum(v)) continue;

      const key = k.toLowerCase();

      // Prompt/input side (OpenAI variants + cache fields)
      if (key === 'prompt_tokens' || key === 'input_tokens' || key === 'request_tokens') {
        prompt += v; found = true;
      }
      if (key === 'cache_creation_input_tokens' || key === 'prompt_cache_miss_tokens') {
        prompt += v; found = true;
      }
      if (key === 'cache_read_input_tokens' || key === 'prompt_cache_hit_tokens') {
        prompt += v; found = true;
      }

      // Completion/output side (OpenAI variants)
      if (key === 'completion_tokens' || key === 'output_tokens' || key === 'response_tokens') {
        completion += v; found = true;
      }

      // Aggregate total if exposed
      if (key === 'total_tokens' || key === 'tokens_total') {
        total += v; found = true;
      }
    }
  }

  // If we only have total + prompt, derive completion
  if (found && completion === 0 && total > 0 && prompt > 0 && total >= prompt) {
    completion = total - prompt;
  }
  // If we only have total (no prompt split), assume 60/40
  if (found && completion === 0 && prompt === 0 && total > 0) {
    prompt = Math.round(total * 0.60);
    completion = total - prompt;
  }
  return { prompt, completion, found };
}

// ~4 chars ≈ 1 token (rough heuristic)
const approxTokens = (s) => Math.ceil(String(s || '').length / 4);

// Pull model output text for fallback (title +/- summary)
function extractGeneratedText(j){
  let title = '', summary = '';
  // Common placements used in your flow
  if (j.output && typeof j.output === 'object') {
    title = j.output.title || '';
    summary = j.output.summary || '';
  } else if (typeof j.output === 'string') {
    try {
      const p = JSON.parse(j.output);
      if (p && typeof p === 'object') {
        title = typeof p.title === 'string' ? p.title : '';
        summary = typeof p.summary === 'string' ? p.summary : '';
      } else {
        title = j.output;
      }
    } catch {
      title = j.output;
    }
  } else if (typeof j.title === 'string') {
    title = j.title;
  }
  return (title + ' ' + summary).trim();
}

// Also include part of the original desc if you pass it to the model
function extractDesc(j){
  const d = j.data && typeof j.data.description_clean === 'string'
    ? j.data.description_clean
    : (j.data && typeof j.data.desc === 'string' ? j.data.desc : '');
  return d || '';
}

// ---- ACCUMULATE OVER ALL ITEMS ----
const items = $items();
let sumPrompt = 0, sumCompletion = 0, usedEstimate = false, count = 0;

// Fallback tunables
const BASE_PROMPT_OVERHEAD     = 500;   // baseline prompt context per item (adjust to your prompt)
const PROMPT_DESC_FRACTION     = 0.10;  // small share of desc counted on prompt side
const MIN_COMPLETION_PER_ITEM  = 1000;   // enforce a non-zero completion
const MIN_COMPLETION_FRACTION  = 0.10;  // completion must be at least 10% of total
const MIN_TOTAL_PER_ITEM       = 1200;  // clamp lower bound of total (p+c)
const MAX_TOTAL_PER_ITEM       = 2100;  // clamp upper bound of total

for (const it of items){
  const j = it.json || {};
  const { prompt, completion, found } = sumUsageDeep(j);

  if (found){
    let p = prompt;
    let c = completion;

    // Some runtimes report completion=0: derive from generated text as a floor
    if (c === 0) {
      const outText = extractGeneratedText(j);
      const estC = Math.max(MIN_COMPLETION_PER_ITEM, approxTokens(outText));
      c = Math.max(c, estC);
    }

    // Enforce completion fraction (helps when prompts are huge)
    const totalNow = p + c;
    const minC = Math.ceil(totalNow * MIN_COMPLETION_FRACTION);
    if (c < minC) c = minC;

    sumPrompt += p;
    sumCompletion += c;
    count++;
    continue;
  }

  // ---- Fallback path: no usage found ----
  usedEstimate = true; count++;

  const outText = extractGeneratedText(j);   // title + optional summary
  const desc    = extractDesc(j);

  let p = BASE_PROMPT_OVERHEAD + Math.round(approxTokens(desc) * PROMPT_DESC_FRACTION);
  let c = Math.max(MIN_COMPLETION_PER_ITEM, approxTokens(outText));

  // Enforce completion share before clamping totals
  const preTotal = p + c;
  const minC = Math.ceil(preTotal * MIN_COMPLETION_FRACTION);
  if (c < minC) c = minC;

  // Clamp total and adjust prompt side first
  let total = p + c;
  if (total < MIN_TOTAL_PER_ITEM) {
    p += (MIN_TOTAL_PER_ITEM - total);
  } else if (total > MAX_TOTAL_PER_ITEM) {
    const trim = total - MAX_TOTAL_PER_ITEM;
    p = Math.max(1, p - trim);
  }

  sumPrompt += p;
  sumCompletion += c;
}

return [{
  title_prompt_tokens: sumPrompt,
  title_completion_tokens: sumCompletion,
  title_tokens_estimated: usedEstimate,
  titles_count: count
}];

// COUNT EVENTS CREATED
// Input: all items emitted by "Create an event" (one per event; failures may include an "error")
// Output: single item with events_created (unique successful events)
// Note: turn "Run Once for All Items" ON in this Code node's settings.

const all = $items();                    // all results from "Create an event"
const isOk = (it) => !it.json?.error;    // treat items with .json.error as failures (when Continue On Fail is used)

// Try to extract a stable event identifier from typical Outlook responses
const getId = (j) => j?.id ?? j?.data?.id ?? j?.["@odata.id"] ?? j?.["@odata.etag"] ?? null;

const okItems = all.filter(isOk);

// Deduplicate by id (if id missing, we still count the item as a success)
const ids = new Set();
let counted = 0;
for (const it of okItems) {
  const id = getId(it.json);
  if (id) {
    if (!ids.has(id)) {
      ids.add(id);
      counted++;
    }
  } else {
    counted++; // count successes with no explicit id once
  }
}

// Optional diagnostics (useful in logs; harmless if unused downstream)
const failures = all.length - okItems.length;

return [{
  events_created: counted,         // <-- use this in your Weekly_Log
  events_attempted: all.length,    // diagnostic
  events_failed: failures          // diagnostic
}];

// ==== Runtime + context ====
const m = $json._metrics || {};
const start = new Date(m.start_ts || new Date().toISOString());
const runtimeSec = Math.max(0, Math.round((Date.now() - start.getTime())/1000));

// ==== Tasks included in the email ====
const tasksInEmail =
  ($json.weekTotal != null ? Number($json.weekTotal) : null) ??
  ($json.Tasks_In_Email != null ? Number($json.Tasks_In_Email) : null) ??
  Number($json.tasks_from_erpnext || 0);

// ==== TOKEN TOTALS (two buckets) ====
// Titles (from TITLE USAGE TAP)
const tp_titles = Number($json.title_prompt_tokens || 0);
const tc_titles = Number($json.title_completion_tokens || 0);

// Email (from metrics if captured; else estimated per task to keep logs stable)
const HAVE_EMAIL_USAGE = !!(m.email_prompt_tokens || m.email_completion_tokens);
const EMAIL_PROMPT_PER_TASK     = 130;   // <— keep/adjust baseline
const EMAIL_COMPLETION_PER_TASK = 117;   // <— keep/adjust baseline

const tp_email = HAVE_EMAIL_USAGE
  ? Number(m.email_prompt_tokens || 0)
  : tasksInEmail * EMAIL_PROMPT_PER_TASK;

const tc_email = HAVE_EMAIL_USAGE
  ? Number(m.email_completion_tokens || 0)
  : tasksInEmail * EMAIL_COMPLETION_PER_TASK;

// ==== FX ====
const USD_TO_EUR = 0.93;  // <— set your FX

// ==== PRICING (USD per 1M tokens) — set each model separately ====
// a) Title generator (gpt-5-nano)
const USD_1M_IN_TITLES   = 0.050;   // <— FILL with your input price
const USD_1M_INC_TITLES  = 0.005;   // <— cached input (if you use caching); else keep small or = input
const USD_1M_OUT_TITLES  = 0.400;   // <— output price

// b) Email composer (gpt-5)
const USD_1M_IN_EMAIL    = 1.250;   // <— your current input price
const USD_1M_INC_EMAIL   = 0.125;   // <— cached input
const USD_1M_OUT_EMAIL   = 10.000;  // <— output price

// Caching share (0..1) per bucket (set to 0 if not using caching)
const CACHE_HIT_TITLES = 0.00;
const CACHE_HIT_EMAIL  = 0.00;

// ---- helpers ----
const eurPer1k = (usdPer1M) => (usdPer1M * USD_TO_EUR) / 1000;

// Effective input €/1k with caching mix
const EUR_IN_TITLES  = (1 - CACHE_HIT_TITLES) * eurPer1k(USD_1M_IN_TITLES)  + CACHE_HIT_TITLES * eurPer1k(USD_1M_INC_TITLES);
const EUR_IN_EMAIL   = (1 - CACHE_HIT_EMAIL)  * eurPer1k(USD_1M_IN_EMAIL)   + CACHE_HIT_EMAIL  * eurPer1k(USD_1M_INC_EMAIL);
const EUR_OUT_TITLES = eurPer1k(USD_1M_OUT_TITLES);
const EUR_OUT_EMAIL  = eurPer1k(USD_1M_OUT_EMAIL);

// ==== COSTS per bucket ====
const costTitlesEUR = (tp_titles / 1000) * EUR_IN_TITLES  + (tc_titles / 1000) * EUR_OUT_TITLES;
const costEmailEUR  = (tp_email  / 1000) * EUR_IN_EMAIL   + (tc_email  / 1000) * EUR_OUT_EMAIL;

// ==== TOTALS ====
const tp_total = tp_titles + tp_email;
const tc_total = tc_titles + tc_email;
const tokenCostEUR_Total = costTitlesEUR + costEmailEUR;

// ==== OUTPUT ROW ====
return [{
  Week_Start: m.week_start,
  Runs: 1,
  Tasks_From_ERPNext: Number($json.tasks_from_erpnext || tasksInEmail || 0),
  Tasks_In_Email: tasksInEmail,
  Events_Created: Number($json.events_created || 0),
  Failures: Number(m.failures || 0),
  Runtime_sec: runtimeSec,
  Actual_Send_Timestamp: m.email_sent_ts || new Date().toISOString(),

  // Tokens by bucket
  Title_Model: 'gpt-5-nano',    // <— optional label
  Email_Model: 'gpt-5',         // <— optional label
  Title_Prompt_Tokens: Math.round(tp_titles),
  Title_Completion_Tokens: Math.round(tc_titles),
  Email_Prompt_Tokens: Math.round(tp_email),
  Email_Completion_Tokens: Math.round(tc_email),

  // Totals
  Prompt_Tokens_Total: Math.round(tp_total),
  Completion_Tokens_Total: Math.round(tc_total),

  // Costs by bucket
  Title_Token_Cost_EUR: Number(costTitlesEUR.toFixed(4)),
  Email_Token_Cost_EUR: Number(costEmailEUR.toFixed(4)),
  Token_Cost_EUR_Total: Number(tokenCostEUR_Total.toFixed(4)),
}];

// POST-EMAIL TIMESTAMP (empty-output friendly)
const primary = ($items()[0]?.json) || {};
const m = { ...(primary._metrics || {}) };

m.email_sent_ts = new Date().toISOString();
m.email_sent_ts_source = 'workflow_clock';

return [{ ...primary, _metrics: m }];

// Combine item 0 (data) and item 1 (output)
const arr = $items().map(i => i.json);
const task = (arr.find(i => i.data) || {}).data || {};
let out = (arr.find(i => i.output) || {}).output;

if (typeof out === 'string') { try { out = JSON.parse(out); } catch {} }

return [{
  title: String(out?.title || '').trim(),
  start: `${task.date}T04:00`,
  end:   `${task.date}T04:15`
}];

parameters.bodyContent:
={{ (() => {
  let v = $('AI E-mail Sender').item.json.output;

  // If the AI returned an object, take .Message; otherwise stringify-to-string
  if (v && typeof v !== 'string') v = v.Message ?? JSON.stringify(v);
  v = String(v ?? '');

  return v
    .replace(/^```(?:html)?|```$/g, '')          // strip code fences
    .replace(/^\s*{\s*"Message"\s*:\s*"|"}\s*$/g, '') // strip {"Message":" ... "}
    .replace(/^"|"$/g, '')                       // stray wrapping quotes
    .replace(/\\"/g, '"')                        // unescape quotes
    .replace(/\\t/g, '')                         // remove \t
    .replace(/\\n\s*/g, '')                      // remove \n  (use '<br>' if you prefer line breaks)
    .trim();
})() }}
